struct MightThrowOnMove {
    // Move operations are not marked noexcept
    MightThrowOnMove(MightThrowOnMove&& other) { /* ... */ }
    MightThrowOnMove& operator=(MightThrowOnMove&& other) { /* ... */ return *this; }
};

struct WontThrowOnMove {
    // Move operations are correctly marked noexcept
    WontThrowOnMove(WontThrowOnMove&& other) noexcept { /* ... */ }
    WontThrowOnMove& operator=(WontThrowOnMove&& other) noexcept { /* ... */ return *this; }
};

